<?php

declare(strict_types=1);

namespace Tests\Unit\Support;

use App\Support\Files;
use App\Support\Format;
use App\Support\Initials;
use App\Support\Pagination;
use PHPUnit\Framework\Attributes\DataProvider;
use Tests\Unit\Content\FixtureTestCase;

/** Fixtures generated by the TS implementation (`tests/Unit/Content/fixtures`). */
final class SupportParityTest extends FixtureTestCase
{
    private static function fixtureFile(string $name): mixed
    {
        return json_decode((string) file_get_contents(__DIR__.'/../Content/fixtures/'.$name.'.json'), true, 512, JSON_THROW_ON_ERROR);
    }

    /** @return array<string, array{array<string, mixed>}> */
    private static function section(string $file, ?string $key = null): array
    {
        $rows = self::fixtureFile($file);
        $rows = $key === null ? $rows : $rows[$key];
        $cases = [];
        foreach ($rows as $index => $row) {
            $cases[$index.' '.json_encode($row, JSON_UNESCAPED_UNICODE)] = [$row];
        }

        return $cases;
    }

    public static function dateCases(): array
    {
        return self::section('format', 'dates');
    }

    public static function rangeCases(): array
    {
        return self::section('format', 'ranges');
    }

    public static function sizeCases(): array
    {
        return self::section('format', 'sizes');
    }

    public static function initialsCases(): array
    {
        return self::section('initials');
    }

    public static function paginationCases(): array
    {
        return self::section('pagination');
    }

    public static function fileCases(): array
    {
        return self::section('files');
    }

    #[DataProvider('dateCases')]
    public function test_format_date(array $case): void
    {
        $this->assertSame($case['out'], Format::formatDate($case['input'], $case['opts']));
    }

    #[DataProvider('rangeCases')]
    public function test_format_date_range(array $case): void
    {
        $this->assertSame($case['out'], Format::formatDateRange($case['start'], $case['end'], $case['opts']));
    }

    #[DataProvider('sizeCases')]
    public function test_format_file_size(array $case): void
    {
        $input = $case['input'] === 'NaN' ? NAN : $case['input'];
        $this->assertSame($case['out'], Format::formatFileSize($input));
    }

    #[DataProvider('initialsCases')]
    public function test_initials(array $case): void
    {
        $this->assertSame($case['out'], Initials::getInitials($case['input']));
    }

    #[DataProvider('paginationCases')]
    public function test_page_window(array $case): void
    {
        $this->assertSame($case['out'], Pagination::pageWindow($case['current'], $case['count']));
    }

    #[DataProvider('fileCases')]
    public function test_files(array $case): void
    {
        $this->assertSame($case['ext'], Files::extensionOf($case['input']));
        $this->assertSame($case['kind'], Files::fileKind($case['ext']));
        $this->assertSame($case['kindDot'], Files::fileKind('.'.$case['input']));
    }
}
